SELECT CASE WHEN ss.units >= 43 THEN 'high' WHEN ss.units >= 7 THEN 'mid' ELSE 'low' END AS units_bucket, COUNT(i.quantity) AS quantity_count FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.product_id IN (3, 5, 6) GROUP BY CASE WHEN ss.units >= 43 THEN 'high' WHEN ss.units >= 7 THEN 'mid' ELSE 'low' END ORDER BY quantity_count DESC, units_bucket LIMIT 10;
